#!/usr/bin/env python3
# Temporary transport for the independently tested replay core.
import base64, zlib, hashlib, pathlib
data = """"""
raw = zlib.decompress(base64.b64decode(data))
assert hashlib.sha256(raw).hexdigest() == "af9b93f154e6813710b31a8b9a0d0b68043437706f9c42c2fdd53e14c88fd4b1"
out = pathlib.Path("roblox/src/shared/HorseCore/Replay.luau")
out.write_bytes(raw)
print("Verified replay source:", hashlib.sha256(raw).hexdigest())
